<template>
    <Modal ref="modal" title="Adjust image" dialog-class="dialog-lg" :footer-close="false" prevent-outside-click @close="releaseEditor">
        <p>Drag to recenter the image. Use the zoom controls or mouse wheel to adjust its size.</p>
        <p v-if="!ready && !error" role="status">Loading image…</p>
        <p v-if="error" class="fg-danger" role="alert">{{ error }}</p>
        <div class="row gy-3 align-items-center">
            <div class="md:col-8">
                <div ref="editor" class="image-cropper-editor mx-auto" :aria-busy="!ready"></div>
            </div>
            <div class="md:col-4 text-center">
                <h6>Avatar preview</h6>
                <div ref="preview" class="image-cropper-preview mx-auto"></div>
                <p class="fg-2 mt-2 mb-0">512 × 512 WebP</p>
            </div>
        </div>
        <div class="d-flex flex-wrap justify-content-center align-items-center gap-2 mt-3">
            <div class="btn-group" role="group" aria-label="Image zoom">
                <button type="button" class="btn btn-primary btn-sm" :disabled="!ready || exporting" aria-label="Zoom out" @click="zoom(-0.15)"><i class="material-icons" aria-hidden="true">zoom_out</i></button>
                <button type="button" class="btn btn-primary btn-sm" :disabled="!ready || exporting" aria-label="Zoom in" @click="zoom(0.15)"><i class="material-icons" aria-hidden="true">zoom_in</i></button>
            </div>
            <div class="btn-group" role="group" aria-label="Image position">
                <button v-for="direction in directions" :key="direction.label" type="button" class="btn btn-default btn-sm" :disabled="!ready || exporting" :aria-label="direction.label" @click="move(direction.x, direction.y)"><i class="material-icons" aria-hidden="true">{{ direction.icon }}</i></button>
            </div>
            <button type="button" class="btn btn-default btn-sm" :disabled="!ready || exporting" @click="resetCrop">Reset</button>
        </div>
        <template #footer>
            <button type="button" class="btn btn-link" @click="$refs.modal.hide()">Cancel</button>
            <button type="button" class="btn btn-primary" :disabled="!ready || exporting" @click="confirmCrop">{{ exporting ? 'Preparing…' : 'Use image' }}</button>
        </template>
    </Modal>
</template>

<script>
import { shallowRef } from 'vue';
import Modal from './Modal.vue';

let nextEditorId = 0;

export default {
    name: 'ImageCropperModal',
    components: { Modal },
    emits: ['confirm'],
    data() {
        return {
            cropper: shallowRef(null),
            resizeObserver: shallowRef(null),
            sourceFile: shallowRef(null),
            sourceUrl: '',
            session: 0,
            canvasWidth: 0,
            ready: false,
            exporting: false,
            error: '',
            directions: [
                { label: 'Move left', icon: 'arrow_back', x: -10, y: 0 },
                { label: 'Move up', icon: 'arrow_upward', x: 0, y: -10 },
                { label: 'Move down', icon: 'arrow_downward', x: 0, y: 10 },
                { label: 'Move right', icon: 'arrow_forward', x: 10, y: 0 },
            ],
        };
    },
    beforeUnmount() {
        this.releaseEditor();
    },
    methods: {
        async show(file) {
            if (this.sourceUrl) {
                return;
            }
            const session = ++this.session;
            this.sourceFile = file;
            this.sourceUrl = URL.createObjectURL(file);
            this.error = '';
            this.ready = false;
            try {
                await this.$refs.modal.show();
                const { default: Cropper } = await import('cropperjs');
                if (session !== this.session || !this.$refs.editor) {
                    return;
                }
                const selectionId = `image-cropper-selection-${++nextEditorId}`;
                const image = new Image();
                image.src = this.sourceUrl;
                image.alt = 'Image to crop';
                this.cropper = new Cropper(image, {
                    container: this.$refs.editor,
                    template: `<cropper-canvas background>
                        <cropper-image initial-fit="cover" min-fit="cover" max-inset="0" scalable translatable zoom-around-center></cropper-image>
                        <cropper-handle action="move" plain></cropper-handle>
                        <cropper-selection id="${selectionId}" aspect-ratio="1" initial-coverage="1">
                            <cropper-grid role="presentation" covered></cropper-grid>
                            <cropper-crosshair centered></cropper-crosshair>
                            <cropper-handle action="move" theme-color="rgba(255, 255, 255, .1)"></cropper-handle>
                        </cropper-selection>
                    </cropper-canvas>`,
                });
                await this.cropper.getCropperImage().$ready();
                if (session !== this.session) {
                    return;
                }
                this.resetCrop();
                const viewer = document.createElement('cropper-viewer');
                viewer.setAttribute('selection', `#${selectionId}`);
                viewer.setAttribute('resize', 'none');
                viewer.style.cssText = 'display:block;width:100%;height:100%';
                this.$refs.preview.append(viewer);
                this.ready = true;
                this.resizeObserver = new ResizeObserver(() => {
                    if (this.ready && this.cropper?.getCropperCanvas().clientWidth !== this.canvasWidth) {
                        this.resetCrop();
                    }
                });
                this.resizeObserver.observe(this.$refs.editor);
            } catch {
                if (session === this.session) {
                    this.ready = false;
                    this.error = 'This image could not be opened. Try another image or convert it to JPEG, PNG, or WebP.';
                }
            }
        },
        resetCrop() {
            const canvas = this.cropper?.getCropperCanvas();
            const image = this.cropper?.getCropperImage();
            const selection = this.cropper?.getCropperSelection();
            if (!canvas || !image || !selection) {
                return;
            }
            this.canvasWidth = canvas.clientWidth;
            selection.$change(0, 0, canvas.clientWidth, canvas.clientHeight, 1);
            image.$resetTransform();
            image.$center('cover');
        },
        zoom(amount) {
            this.cropper?.getCropperImage().$zoom(amount);
        },
        move(x, y) {
            this.cropper?.getCropperImage().$move(x, y);
        },
        async confirmCrop() {
            if (!this.ready || this.exporting) {
                return;
            }
            const session = this.session;
            this.exporting = true;
            this.error = '';
            try {
                const canvas = await this.cropper.getCropperSelection().$toCanvas({
                    width: 512,
                    height: 512,
                    beforeDraw(context, output) {
                        context.fillStyle = '#fff';
                        context.fillRect(0, 0, output.width, output.height);
                        context.imageSmoothingEnabled = true;
                        context.imageSmoothingQuality = 'high';
                    },
                });
                const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', 0.9));
                if (session !== this.session) {
                    return;
                }
                if (!blob || blob.type !== 'image/webp') {
                    throw new Error('WebP export unavailable');
                }
                this.$emit('confirm', new File([blob], 'avatar.webp', { type: 'image/webp' }), this.sourceFile);
                await this.$refs.modal.hide();
            } catch {
                if (session === this.session) {
                    this.error = 'The cropped image could not be prepared. Try resetting the crop or choosing another image.';
                }
            } finally {
                if (session === this.session) {
                    this.exporting = false;
                }
            }
        },
        releaseEditor() {
            this.session++;
            this.ready = false;
            this.exporting = false;
            this.resizeObserver?.disconnect();
            this.resizeObserver = null;
            this.$refs.preview?.replaceChildren();
            this.$refs.editor?.replaceChildren();
            this.cropper = null;
            this.sourceFile = null;
            if (this.sourceUrl) {
                URL.revokeObjectURL(this.sourceUrl);
                this.sourceUrl = '';
            }
        },
    },
};
</script>

<style scoped>
.image-cropper-editor {
    inline-size: min(100%, 360px);
    aspect-ratio: 1;
    overflow: hidden;
    border-radius: var(--radius-2);
}

.image-cropper-editor :deep(cropper-canvas) {
    width: 100%;
    height: auto;
    min-width: 0;
    min-height: 0;
    aspect-ratio: 1;
}

.image-cropper-preview {
    width: 128px;
    height: 128px;
    overflow: hidden;
    border-radius: 50%;
    background: #fff;
    box-shadow: var(--material-card-shadow);
}
</style>
