<template>
    <div class="image-picker text-center" :class="{ 'image-picker-avatar': avatar }">
        <img v-if="previewUrl || placeholder" :src="previewUrl || placeholder" :alt="previewUrl ? previewLabel : ''" />
        <input ref="input" type="file" :accept="accept" :disabled="disabled" hidden @change="selectImage" />
        <div class="d-flex flex-wrap justify-content-center gap-1 mt-2">
            <button type="button" class="btn btn-rose btn-round" :disabled="disabled" :aria-label="modelValue ? changeLabel : label" @click="$refs.input.click()">
                {{ modelValue ? 'Change' : label }}
            </button>
            <button v-if="crop && modelValue" type="button" class="btn btn-primary btn-round" :disabled="disabled" @click="$refs.cropper.show(cropSource || modelValue)">Adjust crop</button>
            <button v-if="modelValue" type="button" class="btn btn-danger btn-round" :disabled="disabled" @click="removeImage">
                <i class="material-icons" aria-hidden="true">close</i> Remove
            </button>
        </div>
        <p v-if="error" class="fg-danger mb-0" role="alert">{{ error }}</p>
        <ImageCropperModal v-if="crop" ref="cropper" @confirm="applyCrop" />
    </div>
</template>

<script>
import { shallowRef } from 'vue';
import ImageCropperModal from './ImageCropperModal.vue';

export default {
    name: 'ImagePicker',
    components: { ImageCropperModal },
    props: {
        modelValue: { type: Object, default: null },
        placeholder: { type: String, default: '' },
        label: { type: String, default: 'Select image' },
        avatar: Boolean,
        accept: { type: String, default: 'image/*' },
        disabled: Boolean,
        crop: Boolean,
    },
    emits: ['update:modelValue'],
    data() {
        return { previewUrl: '', error: '', cropSource: shallowRef(null) };
    },
    computed: {
        changeLabel() {
            return this.avatar ? 'Change avatar' : 'Change image';
        },
        previewLabel() {
            return this.avatar ? 'Selected avatar preview' : 'Selected image preview';
        },
    },
    watch: {
        modelValue: {
            immediate: true,
            handler(file) {
                if (!file) {
                    this.cropSource = null;
                }
                this.releasePreview();
                if (file && typeof window !== 'undefined') {
                    this.previewUrl = URL.createObjectURL(file);
                }
            },
        },
    },
    beforeUnmount() {
        this.releasePreview();
    },
    methods: {
        selectImage(event) {
            const file = event.target.files?.[0];
            event.target.value = '';
            if (!file) {
                return;
            }
            if (file.type && !file.type.startsWith('image/')) {
                this.error = 'Choose an image file.';
                return;
            }
            this.error = '';
            if (this.crop) {
                this.$refs.cropper.show(file);
                return;
            }
            this.$emit('update:modelValue', file);
        },
        applyCrop(file, sourceFile) {
            this.cropSource = sourceFile;
            this.$emit('update:modelValue', file);
        },
        removeImage() {
            this.error = '';
            this.$emit('update:modelValue', null);
        },
        releasePreview() {
            if (this.previewUrl) {
                URL.revokeObjectURL(this.previewUrl);
                this.previewUrl = '';
            }
        },
    },
};
</script>

<style scoped>
.image-picker img {
    display: block;
    inline-size: min(100%, 15rem);
    aspect-ratio: 16 / 10;
    object-fit: cover;
    margin-inline: auto;
    border-radius: var(--radius-3);
    box-shadow: var(--material-card-shadow);
}

.image-picker-avatar img {
    inline-size: min(100%, 8rem);
    aspect-ratio: 1;
    border-radius: 50%;
}
</style>
